using System;
using System.Collections.Generic;
namespace Downfield {
public class CoachRecord {
 public string Name="COACH";public int Wins,Losses,Ties,PlayoffWins,Championships,Skin=1,Hair,Hat=1,Outfit;public bool Initialized;
 public float WinPercent {get{return Wins+Losses+Ties==0?0:100f*(Wins+Ties*.5f)/(Wins+Losses+Ties);}}
}
public class TeamSeason {public int Season,Team,W,L,T,PF,PA,Seed;public bool Champion;public string Name="";}
public class SeasonAward {public int Season,Team;public string Type="",Winner="",Club="",Coach="";public float Score;}
public class SeasonProduction {
 public int PlayerId,Team,PassYards,RushYards,RecYards,PassTD,RushTD,RecTD,Catches,Attempts,Completions,Picks,Games;public string Name="",Role="";
 public float OffenseScore {get{return PassYards*.045f+(RushYards+RecYards)*.1f+PassTD*5+(RushTD+RecTD)*10+Catches*.4f-Picks*2;}}
}
public partial class Franchise {
 public CoachRecord Coach=new CoachRecord();public List<TeamSeason> History=new List<TeamSeason>();public List<SeasonAward> Awards=new List<SeasonAward>();public List<SeasonProduction> Production=new List<SeasonProduction>();public int HistoryVersion=1;
 public void EnsureCareer(){if(Coach==null)Coach=new CoachRecord();if(Coach.Initialized)return;Coach.Initialized=true;foreach(Fixture g in Games)if(g.Played&&g.Involves(UserTeam)){int own=g.Home==UserTeam?g.HomeScore:g.AwayScore,other=g.Home==UserTeam?g.AwayScore:g.HomeScore;if(own>other){Coach.Wins++;if(g.Round>=11)Coach.PlayoffWins++;}else if(own<other)Coach.Losses++;else Coach.Ties++;}Coach.Championships=Titles;}
 public void NameCoach(string name){name=(name??"").Trim().ToUpperInvariant();if(name.Length==0)name="COACH";Coach.Name=name.Substring(0,Math.Min(16,name.Length));Save();}
 void CoachResult(Fixture g){EnsureCareer();int own=g.Home==UserTeam?g.HomeScore:g.AwayScore,other=g.Home==UserTeam?g.AwayScore:g.HomeScore;if(own>other){Coach.Wins++;if(g.Round>=11)Coach.PlayoffWins++;if(g.Round==13)Coach.Championships++;}else if(own<other)Coach.Losses++;else Coach.Ties++;}
 SeasonProduction ProductionFor(ClubPlayer p){SeasonProduction line=Production.Find(x=>x.PlayerId==p.Id);if(line==null){line=new SeasonProduction();line.PlayerId=p.Id;line.Team=p.Team;line.Name=p.Name;line.Role=p.Role;Production.Add(line);}line.Team=p.Team;return line;}
 public void AddBox(int team,List<BoxLine> box){foreach(ClubPlayer player in Squad(team))if(player.Slot>=0&&player.Slot<11&&player.InjuryWeeks==0)ProductionFor(player).Games++;foreach(BoxLine b in box){ClubPlayer p=Players.Find(x=>x.Id==b.PlayerId);if(p==null||p.Team!=team)continue;SeasonProduction line=ProductionFor(p);line.PassYards+=b.PassYards;line.RushYards+=b.RushYards;line.RecYards+=b.RecYards;line.PassTD+=b.PassTD;line.RushTD+=b.RushTD;line.RecTD+=b.RecTD;line.Catches+=b.Catches;line.Attempts+=b.Attempts;line.Completions+=b.Completions;line.Picks+=b.Picks;}}
 void SimulatedBox(Fixture g,int team,int score){Random r=new Random(Season*6731+g.Id*37+team*11);ClubPlayer qb=Starter(team,0),rb=Starter(team,1);List<BoxLine> box=new List<BoxLine>();int totalTD=score/7,passingTD=totalTD==0?0:r.Next(totalTD+1);int passYards=95+r.Next(145)+(Rating(team,false)-75)*4;BoxLine q=new BoxLine();if(qb!=null){q.PlayerId=qb.Id;q.PassYards=passYards;q.PassTD=passingTD;q.Attempts=18+r.Next(15);q.Completions=q.Attempts*(52+(qb.Hands-70))/100;q.Picks=r.Next(3);box.Add(q);}if(rb!=null){BoxLine b=new BoxLine();b.PlayerId=rb.Id;b.RushYards=35+r.Next(70)+(rb.Speed-70)*2;b.RushTD=totalTD-passingTD;box.Add(b);}int remainingYards=passYards,remainingTD=passingTD;int[] slots={2,3,4,10};for(int i=0;i<slots.Length;i++){ClubPlayer receiver=Starter(team,slots[i]);if(receiver==null)continue;BoxLine b=new BoxLine();b.PlayerId=receiver.Id;b.RecYards=i==3?remainingYards:(int)(remainingYards*(.25+r.NextDouble()*.22));remainingYards-=b.RecYards;b.RecTD=i==3?remainingTD:remainingTD>0&&r.Next(2)==0?1:0;remainingTD-=b.RecTD;b.Catches=Math.Max(1,b.RecYards/14);box.Add(b);}AddBox(team,box);}
 void ArchiveSeason(){if(History.Exists(x=>x.Season==Season))return;List<Standing> table=Table();Fixture final=Games.Find(x=>x.Round==13&&x.Played);if(final==null)return;foreach(Standing s in table){TeamSeason entry=new TeamSeason();entry.Season=Season;entry.Team=s.Team;entry.Name=Teams[s.Team].Name;entry.W=s.W;entry.L=s.L;entry.T=s.T;entry.PF=s.PF;entry.PA=s.PA;entry.Seed=Seeds.IndexOf(s.Team)+1;entry.Champion=final.Winner==s.Team;History.Add(entry);}SeasonAward title=new SeasonAward();title.Season=Season;title.Team=final.Winner;title.Type="CHAMPIONSHIP";title.Winner=Teams[title.Team].Name;title.Club=title.Winner;title.Coach=title.Team==UserTeam?Coach.Name:"";Awards.Add(title);
  SeasonProduction mvp=null,op=null;float bestM=-999,bestO=-999;foreach(SeasonProduction p in Production){Standing team=table.Find(t=>t.Team==p.Team);float value=p.OffenseScore+(team==null?0:team.W*4),offense=p.OffenseScore;if(value>bestM){bestM=value;mvp=p;}if(offense>bestO){bestO=offense;op=p;}}if(mvp!=null)AwardPlayer("MVP",mvp,bestM);if(op!=null)AwardPlayer("OPOTY",op,bestO);}
 void AwardPlayer(string type,SeasonProduction p,float score){SeasonAward award=new SeasonAward();award.Season=Season;award.Team=p.Team;award.Type=type;award.Winner=p.Name;award.Club=Teams[p.Team].Name;award.Coach=p.Team==UserTeam?Coach.Name:"";award.Score=score;Awards.Add(award);}
 public bool JoinClub(int team){if(team<0||team>=12)return false;if(Round!=0&&Round!=14||Round==0&&Games.Exists(g=>g.Played)){Notice="Change clubs between seasons.";return false;}EnsureCareer();UserTeam=team;Log(Coach.Name+" joins "+Club.Name+".");Save();return true;}
}
}
